{
  "root_causes": [
    {
      "service": "ts-route-service",
      "fault_kind": "database_call_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, count(*) n, round(quantile_cont(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name='ts-route-service' AND span_name LIKE 'SELECT ts.route%' GROUP BY span_name ORDER BY p95_ms DESC",
          "claim": "Route-service's own SELECT spans on ts.route tables reach p95 of hundreds of ms in the abnormal period, versus about 0.3 ms normally."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, count(*) n, round(quantile_cont(duration,0.95)/1e6,1) p95_ms FROM normal_traces WHERE service_name='ts-route-service' AND span_name LIKE 'SELECT ts.route%' GROUP BY span_name ORDER BY p95_ms DESC",
          "claim": "Normal-period route-service SELECT spans on ts.route tables stay below about 0.6 ms p95."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, count(*) n, round(quantile_cont(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name='ts-route-service' AND span_name IN ('Transaction.commit','RouteController.queryAll','RouteRepository.findAll') GROUP BY span_name",
          "claim": "Route-service's own handlers and Transaction.commit are slow in the abnormal period, consistent with slow database calls underneath them."
        },
        {
          "kind": "metric",
          "sql": "SELECT service_name, metric, round(avg(value),3) avg_v, round(max(value),3) max_v FROM abnormal_metrics WHERE service_name='ts-route-service' AND metric IN ('container.cpu.usage','container.memory.usage') GROUP BY ALL",
          "claim": "Route-service CPU and memory stay flat in the abnormal period (CPU ~0.01 cores), so container saturation is not the cause."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-route-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name parent_svc, c.service_name child_svc, count(*) n, round(quantile_cont(c.duration,0.95)/1e6,1) child_p95_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE p.service_name='ts-ui-dashboard' AND c.service_name='ts-route-service' GROUP BY ALL",
          "claim": "The UI dashboard's calls into route-service slow to multi-second p95, so user-facing route requests are slowed."
        }
      ]
    },
    {
      "from": "ts-route-service",
      "to": "ts-route-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name parent_svc, c.service_name child_svc, count(*) n, round(quantile_cont(c.duration,0.95)/1e6,1) child_p95_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE p.service_name='ts-route-plan-service' AND c.service_name='ts-route-service' GROUP BY ALL",
          "claim": "Route-plan-service's calls to route-service show multi-second p95 latency in the abnormal period."
        }
      ]
    },
    {
      "from": "ts-route-service",
      "to": "ts-basic-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name parent_svc, c.service_name child_svc, c.span_name, count(*) n, round(quantile_cont(c.duration,0.95)/1e6,1) child_p95_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE p.service_name='ts-basic-service' AND c.service_name='ts-route-service' GROUP BY ALL",
          "claim": "Basic-service's calls to route-service byIds show a p95 of about 665 ms, versus about 2.6 ms normally."
        }
      ]
    },
    {
      "from": "ts-route-plan-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name parent_svc, c.service_name child_svc, count(*) n, round(quantile_cont(c.duration,0.95)/1e6,1) child_p95_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE p.service_name='ts-travel-plan-service' AND c.service_name='ts-route-plan-service' GROUP BY ALL",
          "claim": "Travel-plan-service's calls to route-plan-service take seconds at p95, and travel-plan's own handlers are slow too."
        }
      ]
    },
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name parent_svc, c.service_name child_svc, count(*) n, round(quantile_cont(c.duration,0.95)/1e6,1) child_p95_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE p.service_name='ts-ui-dashboard' AND c.service_name='ts-travel-plan-service' GROUP BY ALL",
          "claim": "The UI dashboard's travel-plan requests show seconds-long p95 latency in the abnormal period."
        }
      ]
    }
  ]
}
